import sys

data = sys.stdin.read().split()
n = int(data[0])
s = data[1:1 + n]

def similar(a, b):
    if a == b:
        return True
    L = len(a)
    for i in range(L):
        for j in range(i + 1, L):
            t = list(a)
            t[i], t[j] = t[j], t[i]
            if ''.join(t) == b:
                return True
    return False

seen = [False] * n
count = 0
for i in range(n):
    if seen[i]:
        continue
    count += 1
    seen[i] = True
    stack = [i]
    while stack:
        u = stack.pop()
        for v in range(n):
            if not seen[v] and similar(s[u], s[v]):
                seen[v] = True
                stack.append(v)
print(count)

